    if call, ok := c.Node().(*ast.CallExpr); ok {
        if id, ok := call.Fun.(*ast.Ident); ok && id.Name == "pred" {
            c.Replace(&ast.UnaryExpr{Op: token.NOT, X: call})  // pred() -> !pred()
        }
    }
